 policy()?;let c30=native_gpu_c30::state();if !c30.qualified{return Err("K14.C31 requires frozen qualified C30")};let owner=if crate::native_gpu_c27::state().forge_device!=0{crate::native_gpu_c27::state().forge_device}else{0xc030};let caps=radeon_compute_caps::current()?;let qfp=radeon_command::queue_self_test()?;let scfp=radeon_shader_cache::self_test()?;let compute=radeon_compute::qualify(allocator,owner)?;let graphics=radeon_graphics::qualify(allocator,boot_info,owner,c30)?;let(ins,hits,miss,precache)=radeon_shader_cache::counters();if ins<3||hits<1||precache<3{return Err("C31 live shader cache/precache counters invalid")};
