 serial::println(format_args!("[C31HC] compute capability model: address_bits={} dimensions={} max_workgroup={} separate_compute={} separate_graphics={} timeline_fence={} host_visible_GTT={} native_AMD_ISA={} physical_dispatch={}",caps.address_bits,caps.dispatch_dimensions,caps.max_workgroup_x,caps.separate_compute_queue,caps.separate_graphics_queue,caps.timeline_fence,caps.host_visible_gtt,caps.native_amd_isa,caps.physical_dispatch));
